import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.9yf7n3zg.js";const a="/guide/media/keys-view-help.webp",s="/guide/media/keys-settings-hotkeys.webp",u=JSON.parse('{"title":"Keys and commands","description":"","frontmatter":{},"headers":[],"relativePath":"reference/keys.md","filePath":"reference/keys.md","lastUpdated":1792685126000}'),n={name:"reference/keys.md"};function i(c,t,h,l,p,g){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keys-and-commands" tabindex="-1">Keys and commands <a class="header-anchor" href="#keys-and-commands" aria-label="Permalink to &quot;Keys and commands&quot;">​</a></h1><p>Every command Leathercase answers, with its key, where it works and what it does, then the keys each view answers while it is on screen, and how to change any of them. Keys are written for Windows and Linux; on macOS, use <code>Cmd</code> wherever this page says <code>Ctrl</code>, and <code>Option</code> for <code>Alt</code>.</p><p>Three ways reach every command:</p><ul><li>its <strong>key</strong>, when it has one;</li><li>the <strong>menu bar</strong> (File, Edit, Story, View, Window), built from the same list, so the two never disagree;</li><li>the <strong>find field</strong> in the title bar (<code>Ctrl+K</code>): type part of a command&#39;s name and press <code>Enter</code>. The commands you used last come first.</li></ul><p>To see the keys of the view you are in, press <code>?</code> (when you are not typing in a field). A panel titled <strong>Keys of this view</strong> lists them; <code>?</code> or <code>Esc</code> closes it.</p><p><img src="'+a+`" alt="The plot grid with the Keys of this view panel open, listing the grid&#39;s keys" width="565" height="722" loading="lazy"></p><h2 id="where-a-command-works" tabindex="-1">Where a command works <a class="header-anchor" href="#where-a-command-works" aria-label="Permalink to &quot;Where a command works&quot;">​</a></h2><p>Each command has a scope. A command outside its scope is not offered in the find field and does nothing when its key is pressed.</p><table tabindex="0"><thead><tr><th>Scope</th><th>The command works</th></tr></thead><tbody><tr><td>Always</td><td>On every screen, even before a writing home is open</td></tr><tr><td>With a home open</td><td>Once a writing home is open</td></tr><tr><td>With a story open</td><td>While one of the home&#39;s stories is open in a view</td></tr></tbody></table><p>A story view&#39;s command (Plot grid, Threads and the like) pressed when no story is open opens that view of the story you worked on last.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><h3 id="go" tabindex="-1">Go <a class="header-anchor" href="#go" aria-label="Permalink to &quot;Go&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Key</th><th>Scope</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Library</strong></td><td><code>Ctrl+1</code></td><td>With a home open</td><td>The home&#39;s start page, with its stories</td></tr><tr><td><strong>Desk</strong></td><td><code>Ctrl+2</code></td><td>With a home open</td><td>The Desk; see <a href="/guide/guide/desk">The Desk</a></td></tr><tr><td><strong>Writer</strong></td><td><code>Ctrl+3</code></td><td>With a home open</td><td>The Writer Board; see <a href="/guide/guide/writer-board">The Writer Board</a></td></tr><tr><td><strong>Plot grid</strong></td><td><code>Ctrl+4</code></td><td>With a home open</td><td>The story&#39;s plot grid; see <a href="/guide/guide/plot-grid">Plot grid</a></td></tr><tr><td><strong>Threads</strong></td><td><code>Ctrl+5</code></td><td>With a home open</td><td>The story&#39;s threads; see <a href="/guide/guide/threads">Threads</a></td></tr><tr><td><strong>Graph</strong></td><td><code>Ctrl+6</code></td><td>With a home open</td><td>The story&#39;s graph; see <a href="/guide/guide/graph">Graph</a></td></tr><tr><td><strong>Manuscript</strong></td><td><code>Ctrl+7</code></td><td>With a home open</td><td>The manuscript; see <a href="/guide/guide/manuscript">Manuscript</a></td></tr><tr><td><strong>Tags</strong></td><td><code>Ctrl+8</code></td><td>With a home open</td><td>The home&#39;s tags; see <a href="/guide/guide/tags">Tags</a></td></tr><tr><td><strong>Beat board</strong></td><td><code>Ctrl+9</code></td><td>With a home open</td><td>The story&#39;s beat board; see <a href="/guide/guide/beat-board">Beat board</a></td></tr><tr><td><strong>Inbox</strong></td><td><code>Ctrl+0</code></td><td>With a home open</td><td>What agents proposed; see <a href="/guide/guide/inbox">Proposals and the inbox</a></td></tr><tr><td><strong>Characters</strong></td><td>none</td><td>With a home open</td><td>The story&#39;s characters; see <a href="/guide/guide/characters">Characters</a></td></tr><tr><td><strong>How this story is read</strong></td><td>none</td><td>With a home open</td><td>What Leathercase found in the story&#39;s folder and why; see <a href="/guide/guide/how-a-story-is-read">How a story is read</a></td></tr></tbody></table><h3 id="story" tabindex="-1">Story <a class="header-anchor" href="#story" aria-label="Permalink to &quot;Story&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Key</th><th>Scope</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Declare a story</strong></td><td>none</td><td>With a home open</td><td>Starts declaring a new story in the home; see <a href="/guide/guide/declare-a-story">Declaring a story</a></td></tr><tr><td><strong>Story settings</strong></td><td>none</td><td>With a story open</td><td>The open story&#39;s settings page; see <a href="/guide/guide/story-settings">Story settings</a></td></tr><tr><td><strong>Export the manuscript as one file</strong></td><td><code>Ctrl+E</code></td><td>With a story open</td><td>Exports the open story at once: the save dialog opens, with the settings already saved for the story. The export settings themselves are in <strong>Settings › Export</strong> for the story; see <a href="/guide/guide/export">Export</a></td></tr><tr><td><strong>Open the story in your software</strong></td><td><code>Ctrl+Shift+O</code></td><td>With a story open</td><td>Opens the story&#39;s files in the app you write in</td></tr><tr><td><strong>Mark the sentence log</strong></td><td>none</td><td>With a story open</td><td>Opens the find field with <code>mark: </code> typed, to name a mark in the sentence log; see <a href="/guide/guide/sentence-log">Sentence log</a></td></tr><tr><td><strong>Run the mate now</strong></td><td>none</td><td>With a story open</td><td>The mate looks at the open story at once; see <a href="/guide/guide/mate">The mate</a></td></tr><tr><td><strong>Next proposal</strong></td><td><code>Ctrl+]</code></td><td>With a story open</td><td>Picks the next proposal and opens the Proposals sheet</td></tr><tr><td><strong>Previous proposal</strong></td><td><code>Ctrl+[</code></td><td>With a story open</td><td>Picks the previous proposal</td></tr><tr><td><strong>Accept the proposal</strong></td><td><code>Ctrl+Shift+Enter</code></td><td>With a story open</td><td>Accepts the picked proposal, then picks the next</td></tr><tr><td><strong>Dismiss the proposal</strong></td><td><code>Ctrl+Shift+Backspace</code></td><td>With a story open</td><td>Dismisses the picked proposal, then picks the next</td></tr><tr><td>Next proposal, in a review</td><td><code>Tab</code> · <code>Shift+Tab</code></td><td>Reviewing a changeset, from the page or a proposal</td><td>Picks the next or previous proposal of this view; see <a href="/guide/guide/inbox#reviewing-in-a-view">Reviewing in a view</a></td></tr><tr><td>Accept, dismiss, edit, in a review</td><td><code>A</code> · <code>D</code> · <code>E</code></td><td>Reviewing a changeset, not in a field</td><td>Accepts, dismisses or opens to edit the picked proposal</td></tr></tbody></table><h3 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Key</th><th>Scope</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Search in this view</strong></td><td><code>Ctrl+F</code></td><td>With a home open</td><td>Puts the cursor in the view&#39;s own search field; in the Graph it opens the side column to it; where a view has none, it opens the find field</td></tr><tr><td><strong>Find or make in this view</strong></td><td><code>Ctrl+O</code></td><td>With a home open</td><td>Opens the find field in the title bar; see <a href="/guide/guide/find">Find, open and make</a></td></tr><tr><td><strong>Show or hide the assistant&#39;s layer</strong></td><td><code>Ctrl+.</code></td><td>With a home open</td><td>Hides or shows what agents and the mate left on the views; remembered</td></tr><tr><td><strong>Proposals for this story</strong></td><td><code>Ctrl+Shift+.</code></td><td>With a story open</td><td>Opens or closes the Proposals sheet in the side column</td></tr><tr><td><strong>Zoom in</strong></td><td><code>Ctrl+=</code></td><td>Always</td><td>Draws the whole window larger, words and controls together, one step up to 300%; remembered</td></tr><tr><td><strong>Zoom out</strong></td><td><code>Ctrl+-</code></td><td>Always</td><td>Draws the whole window smaller, one step down to 50%</td></tr><tr><td><strong>Actual size</strong></td><td>none</td><td>Always</td><td>Puts the window back at 100%. The zoom is also in <strong>Settings › Accessibility</strong></td></tr></tbody></table><h3 id="app" tabindex="-1">App <a class="header-anchor" href="#app" aria-label="Permalink to &quot;App&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Key</th><th>Scope</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Find a story, a view or a command</strong></td><td><code>Ctrl+K</code></td><td>Always</td><td>Opens or closes the find field</td></tr><tr><td><strong>Add a writing home</strong></td><td>none</td><td>Always</td><td>Picks a folder to open as a writing home; see <a href="/guide/guide/homes-and-stories">Homes and stories</a></td></tr><tr><td><strong>Settings</strong></td><td><code>Ctrl+,</code></td><td>Always</td><td>The Settings page; see <a href="/guide/reference/settings">Settings</a></td></tr><tr><td><strong>Check for updates</strong></td><td>none</td><td>Always</td><td>Opens Settings at Updates and asks which version is newest; see <a href="/guide/reference/updates">Updates and uninstalling</a></td></tr><tr><td><strong>About Leathercase</strong></td><td>none</td><td>Always</td><td>Opens Settings at About: the version, whether a newer one is out, and where every version is</td></tr><tr><td><strong>Collapse or expand the sidebar</strong></td><td><code>Ctrl+\\</code></td><td>Always</td><td>Folds the sidebar to icons, or opens it; remembered</td></tr><tr><td><strong>Toggle the side column</strong></td><td><code>Ctrl+B</code></td><td>With a home open</td><td>Opens or closes the view&#39;s side column; closes the Proposals sheet when it is open</td></tr><tr><td><strong>Show or hide the mate</strong></td><td><code>Ctrl+Shift+M</code></td><td>Always</td><td>Opens or closes the mate&#39;s panel; remembered</td></tr><tr><td><strong>Theme: light</strong></td><td>none</td><td>Always</td><td>Light theme</td></tr><tr><td><strong>Theme: dark</strong></td><td>none</td><td>Always</td><td>Dark theme</td></tr><tr><td><strong>Theme: follow the desktop</strong></td><td>none</td><td>Always</td><td>Follows the system&#39;s light or dark setting</td></tr></tbody></table><p>Keys with <code>Ctrl</code> work everywhere, even while you type in a field. A key with no <code>Ctrl</code> never runs a command while you type in a field, and <code>Tab</code> is never taken: it always moves between controls.</p><h2 id="the-menu-bar" tabindex="-1">The menu bar <a class="header-anchor" href="#the-menu-bar" aria-label="Permalink to &quot;The menu bar&quot;">​</a></h2><p>The menu bar holds the same commands, in the app&#39;s language. The items the system provides (Undo, Copy, Quit and the like) are worded by the system.</p><table tabindex="0"><thead><tr><th>Menu</th><th>Items</th></tr></thead><tbody><tr><td><strong>Leathercase</strong> (macOS)</td><td>About Leathercase · Services · Hide, Hide Others, Show All · Quit</td></tr><tr><td><strong>File</strong></td><td>Add a writing home, Declare a story · Settings, Check for updates · Quit (Close on macOS)</td></tr><tr><td><strong>Edit</strong></td><td>Undo, Redo · Cut, Copy, Paste, Paste and Match Style, Delete, Select All</td></tr><tr><td><strong>Story</strong></td><td>Story settings · Export the manuscript as one file, Open the story in your software, Mark the sentence log · Run the mate now</td></tr><tr><td><strong>View</strong></td><td>Desk, Inbox, Tags, Graph, Beat board, Plot grid, Threads, Characters, Manuscript, How this story is read · Library, Find a story, a view or a command, Search in this view, Show or hide the assistant&#39;s layer, Proposals for this story, Collapse or expand the sidebar, Toggle the side column, Show or hide the mate · Zoom in, Zoom out, Actual size · Theme: light, Theme: dark, Theme: follow the desktop</td></tr><tr><td><strong>Window</strong></td><td>Minimize, Zoom</td></tr><tr><td><strong>Help</strong> (Windows and Linux)</td><td>About Leathercase</td></tr></tbody></table><p>On macOS the application menu (About, Hide, Quit) comes first, as for every Mac app. The Edit menu is what gives fields <code>Cmd+C</code>, <code>Cmd+V</code> and <code>Cmd+Z</code> on a Mac.</p><h2 id="keys-inside-a-view" tabindex="-1">Keys inside a view <a class="header-anchor" href="#keys-inside-a-view" aria-label="Permalink to &quot;Keys inside a view&quot;">​</a></h2><p>Each view answers some single keys while it is on screen. They are dead while you type in a field, do nothing while a dialog or menu is open, and leave <code>Enter</code>, <code>Space</code> and <code>Delete</code> to a button that has the focus. Press <code>?</code> in any view to see its list.</p><h3 id="plot-grid" tabindex="-1">Plot grid <a class="header-anchor" href="#plot-grid" aria-label="Permalink to &quot;Plot grid&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>←</code> <code>→</code> <code>↑</code> <code>↓</code></td><td>Move between cells</td></tr><tr><td><code>Home</code> / <code>End</code></td><td>First or last column of the row</td></tr><tr><td><code>Page Up</code> / <code>Page Down</code></td><td>Ten rows up or down</td></tr><tr><td><code>Enter</code></td><td>Edit in the cell</td></tr><tr><td><code>Esc</code></td><td>Put it back: cancel the anchor pick, then clear the selection</td></tr><tr><td><code>Delete</code> or <code>Backspace</code></td><td>Remove the stop in the selected cell</td></tr><tr><td><code>&quot;</code></td><td>Anchor the selected cell on a quoted sentence</td></tr><tr><td><code>n</code> / <code>p</code></td><td>Next or previous broken anchor, or a gauge flip no quote marks</td></tr><tr><td><code>o</code></td><td>Open the scene of the selected row</td></tr><tr><td><code>v</code></td><td>Audit view on or off</td></tr><tr><td><code>Ctrl+Z</code> / <code>Ctrl+Shift+Z</code></td><td>Undo / redo the last write</td></tr></tbody></table><p>While editing a cell: <code>Enter</code> writes it, <code>Shift+Enter</code> starts a new line, <code>Esc</code> cancels. See <a href="/guide/guide/plot-grid">Plot grid</a>.</p><h3 id="beat-board" tabindex="-1">Beat board <a class="header-anchor" href="#beat-board" aria-label="Permalink to &quot;Beat board&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>←</code> <code>→</code></td><td>Previous or next card</td></tr><tr><td><code>Enter</code></td><td>Write the selected card</td></tr><tr><td><code>n</code></td><td>New card in the selected column (or loose)</td></tr><tr><td><code>Delete</code> or <code>Backspace</code></td><td>Delete the selected card</td></tr><tr><td><code>Ctrl+Z</code> / <code>Ctrl+Shift+Z</code></td><td>Undo / redo</td></tr><tr><td><code>Esc</code></td><td>Deselect</td></tr></tbody></table><p>Double-click a card to edit its title and text in place: <code>Ctrl+Enter</code> saves, <code>Esc</code> cancels. See <a href="/guide/guide/beat-board#editing-a-card-in-place">Beat board</a>.</p><h3 id="threads" tabindex="-1">Threads <a class="header-anchor" href="#threads" aria-label="Permalink to &quot;Threads&quot;">​</a></h3><p>On the chart:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>+</code> or <code>=</code> / <code>-</code></td><td>Zoom in / out</td></tr><tr><td><code>f</code> or <code>0</code></td><td>Fit the manuscript</td></tr><tr><td><code>Esc</code></td><td>Clear the selection</td></tr><tr><td><code>Ctrl+Z</code> / <code>Ctrl+Shift+Z</code></td><td>Undo / redo the last write</td></tr></tbody></table><p>As lanes:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Previous or next thread</td></tr><tr><td><code>Enter</code></td><td>Go to the thread&#39;s first stop</td></tr><tr><td><code>Esc</code></td><td>Clear</td></tr></tbody></table><h3 id="graph" tabindex="-1">Graph <a class="header-anchor" href="#graph" aria-label="Permalink to &quot;Graph&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>Next name</td></tr><tr><td><code>←</code> <code>→</code> <code>↑</code> <code>↓</code></td><td>The nearest name that way, or pan when nothing is pinned</td></tr><tr><td><code>Enter</code></td><td>Pin what is under the pointer</td></tr><tr><td><code>c</code></td><td>A tie from the pinned name</td></tr><tr><td><code>p</code></td><td>Paths from the pinned name</td></tr><tr><td><code>f</code></td><td>Focus on the pinned name and its neighbours, and back</td></tr><tr><td><code>m</code></td><td>Matrix, and back</td></tr><tr><td><code>z</code> / <code>Shift+Z</code></td><td>Fold the group / every group</td></tr><tr><td><code>Delete</code></td><td>Remove the pinned tie</td></tr><tr><td><code>+</code> or <code>=</code> / <code>-</code></td><td>Zoom in / out</td></tr><tr><td><code>0</code></td><td>Fit everything</td></tr><tr><td>Drag from a name&#39;s ring</td><td>Make a tie</td></tr><tr><td>Double-click</td><td>Open the note</td></tr><tr><td><code>Esc</code></td><td>Let go</td></tr></tbody></table><p>The tie picker: <code>1</code> to <code>5</code> pick a type, <code>Tab</code> goes to the word, <code>X</code> flips the direction, <code>Enter</code> saves, <code>Esc</code> drops it. The matrix: the arrows move a cell, <code>Enter</code> opens its tie.</p><h3 id="manuscript" tabindex="-1">Manuscript <a class="header-anchor" href="#manuscript" aria-label="Permalink to &quot;Manuscript&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td>Click</td><td>Select a sentence</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>Previous or next paragraph</td></tr><tr><td><code>Alt+↑</code> / <code>Alt+↓</code></td><td>Previous or next chapter (note)</td></tr><tr><td><code>Home</code> / <code>End</code></td><td>First or last paragraph</td></tr><tr><td><code>Enter</code> or <code>Ctrl+Enter</code></td><td>Open the selected passage in its app</td></tr><tr><td><code>Ctrl+J</code></td><td>Next broken anchor</td></tr><tr><td><code>l</code></td><td>Next lens</td></tr><tr><td><code>Esc</code></td><td>Close the review, then clear the selection, then turn the lens off</td></tr></tbody></table><p>In the comments pane, <code>Enter</code> sends a comment and <code>Shift+Enter</code> starts a new line.</p><h3 id="writer-board" tabindex="-1">Writer Board <a class="header-anchor" href="#writer-board" aria-label="Permalink to &quot;Writer Board&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Ctrl+O</code></td><td>Find or make a card</td></tr><tr><td><code>←</code> <code>→</code> (or <code>↑</code> <code>↓</code>)</td><td>Previous or next card</td></tr><tr><td><code>Enter</code></td><td>Edit a card Leathercase made, or open your own note</td></tr><tr><td><code>n</code></td><td>New card in the selected list</td></tr><tr><td><code>m</code></td><td>Move the selected card</td></tr><tr><td><code>f</code></td><td>Fit</td></tr><tr><td><code>e</code></td><td>Every line on or off</td></tr><tr><td><code>+</code> / <code>-</code></td><td>Zoom in / out</td></tr><tr><td><code>Esc</code></td><td>Deselect</td></tr></tbody></table><h3 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Previous or next tag</td></tr><tr><td><code>Enter</code></td><td>Open the tag&#39;s first note</td></tr><tr><td><code>Esc</code></td><td>Deselect</td></tr></tbody></table><h3 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h3><p>On <strong>Settings</strong>, <strong>Story settings</strong> and the declaring pages, <code>Esc</code> goes back (on Settings, to the Library; from the uninstall guide, back to Settings).</p><h2 id="the-find-field" tabindex="-1">The find field <a class="header-anchor" href="#the-find-field" aria-label="Permalink to &quot;The find field&quot;">​</a></h2><p>While the find field is open:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Move through the results</td></tr><tr><td><code>Enter</code></td><td>Run or open the picked result</td></tr><tr><td><code>Esc</code></td><td>Close</td></tr><tr><td><code>word: title</code></td><td>Typing a kind, a colon and a title offers to make it, for example <code>character: Nora</code></td></tr></tbody></table><p>A command named with a word and a colon, such as <strong>Theme: light</strong>, still runs when its full name is typed: it comes first, above the <strong>Make</strong> row.</p><p>See <a href="/guide/guide/find">Find, open and make</a> and, for questions and meaning search, <a href="/guide/guide/mate#the-mate-in-the-find-field">The mate</a>.</p><h2 id="menus-and-dialogs" tabindex="-1">Menus and dialogs <a class="header-anchor" href="#menus-and-dialogs" aria-label="Permalink to &quot;Menus and dialogs&quot;">​</a></h2><p>A menu or dialog keeps its keys to itself: <code>Esc</code> closes it, and the view behind it takes no key while it is open. The agents menu in the title bar closes with <code>Esc</code> too.</p><h2 id="keys-that-work-anywhere-on-this-computer" tabindex="-1">Keys that work anywhere on this computer <a class="header-anchor" href="#keys-that-work-anywhere-on-this-computer" aria-label="Permalink to &quot;Keys that work anywhere on this computer&quot;">​</a></h2><p>Two keys can work even when another app is in front. They are <strong>off by default</strong>, so Leathercase takes no key from other apps until you ask.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Capture to Writer</strong></td><td><code>Ctrl+Shift+N</code></td><td>Opens a small window over any app; what you type lands in the Writer&#39;s Ideas. In that window, <code>Ctrl+Enter</code> keeps it and <code>Esc</code> closes it</td></tr><tr><td><strong>Show Leathercase</strong></td><td><code>Ctrl+Shift+S</code></td><td>Brings Leathercase forward from any app</td></tr></tbody></table><p>Turn them on in <strong>Settings › Hotkeys › Anywhere on this computer</strong> with <strong>Turn on global keys</strong>. To change one, click its key and press the new keys. If another app already holds a key, the row says so in amber, &quot;Another app holds this key, so pressing it does nothing here&quot;, and you can pick another; if the system cannot hold it at all, it says &quot;The system cannot hold this key.&quot; <strong>Turn off global keys</strong> gives them back to other apps. These two keys are kept in this computer&#39;s <code>preferences.json</code>.</p><h2 id="changing-keys" tabindex="-1">Changing keys <a class="header-anchor" href="#changing-keys" aria-label="Permalink to &quot;Changing keys&quot;">​</a></h2><p>Every command&#39;s key can be changed or removed in <code>keybindings.json</code>, a file in the app&#39;s data. Open it from <strong>Settings › Hotkeys</strong> with <strong>Edit keybindings.json</strong>; it opens in your text editor.</p><ul><li>The file holds your changes only, and starts empty: <code>{ }</code>. A key the app changes in a later version reaches you unless you overrode it.</li><li>Beside it, <code>keybindings.defaults.json</code> lists every command&#39;s id and default key, rewritten each time; copy a line from it.</li><li>Write one line per command: the command&#39;s id (shown in grey in Settings › Hotkeys), then its key. Write <code>Mod</code> for <code>Ctrl</code> (it becomes <code>Cmd</code> on macOS), and <code>null</code> to remove a key.</li><li>Leathercase reads the file the next time it starts.</li></ul><p>For example, to give <strong>Characters</strong> a key and take <strong>Export</strong> off <code>Ctrl+E</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;go.characters&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Mod+Shift+C&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;story.export&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Settings › Hotkeys</strong> lists every command with its id and its key as it stands, so you can check the result.</p><p><img src="`+s+'" alt="Settings › Hotkeys, with the two global keys off and the table of commands, ids and keys" width="880" height="825" loading="lazy"></p><h2 id="command-ids" tabindex="-1">Command ids <a class="header-anchor" href="#command-ids" aria-label="Permalink to &quot;Command ids&quot;">​</a></h2><p>The ids, for <code>keybindings.json</code>:</p><table tabindex="0"><thead><tr><th>Id</th><th>Command</th><th>Default</th></tr></thead><tbody><tr><td><code>go.start</code></td><td>Library</td><td><code>Mod+1</code></td></tr><tr><td><code>go.desk</code></td><td>Desk</td><td><code>Mod+2</code></td></tr><tr><td><code>go.writer</code></td><td>Writer</td><td><code>Mod+3</code></td></tr><tr><td><code>go.grid</code></td><td>Plot grid</td><td><code>Mod+4</code></td></tr><tr><td><code>go.threads</code></td><td>Threads</td><td><code>Mod+5</code></td></tr><tr><td><code>go.map</code></td><td>Graph</td><td><code>Mod+6</code></td></tr><tr><td><code>go.manuscript</code></td><td>Manuscript</td><td><code>Mod+7</code></td></tr><tr><td><code>go.tags</code></td><td>Tags</td><td><code>Mod+8</code></td></tr><tr><td><code>go.beats</code></td><td>Beat board</td><td><code>Mod+9</code></td></tr><tr><td><code>go.inbox</code></td><td>Inbox</td><td><code>Mod+0</code></td></tr><tr><td><code>go.characters</code></td><td>Characters</td><td>none</td></tr><tr><td><code>go.files</code></td><td>How this story is read</td><td>none</td></tr><tr><td><code>story.declare</code></td><td>Declare a story</td><td>none</td></tr><tr><td><code>story.settings</code></td><td>Story settings</td><td>none</td></tr><tr><td><code>story.export</code></td><td>Export the manuscript as one file</td><td><code>Mod+E</code></td></tr><tr><td><code>story.open</code></td><td>Open the story in your software</td><td><code>Mod+Shift+O</code></td></tr><tr><td><code>story.markLog</code></td><td>Mark the sentence log</td><td>none</td></tr><tr><td><code>mate.run</code></td><td>Run the mate now</td><td>none</td></tr><tr><td><code>view.search</code></td><td>Search in this view</td><td><code>Mod+F</code></td></tr><tr><td><code>view.open</code></td><td>Find or make in this view</td><td><code>Mod+O</code></td></tr><tr><td><code>view.layer</code></td><td>Show or hide the assistant&#39;s layer</td><td><code>Mod+.</code></td></tr><tr><td><code>view.proposals</code></td><td>Proposals for this story</td><td><code>Mod+Shift+.</code></td></tr><tr><td><code>view.zoomIn</code></td><td>Zoom in</td><td><code>Mod+=</code></td></tr><tr><td><code>view.zoomOut</code></td><td>Zoom out</td><td><code>Mod+-</code></td></tr><tr><td><code>view.zoomReset</code></td><td>Actual size</td><td>none</td></tr><tr><td><code>proposal.next</code></td><td>Next proposal</td><td><code>Mod+]</code></td></tr><tr><td><code>proposal.previous</code></td><td>Previous proposal</td><td><code>Mod+[</code></td></tr><tr><td><code>proposal.accept</code></td><td>Accept the proposal</td><td><code>Mod+Shift+Enter</code></td></tr><tr><td><code>proposal.dismiss</code></td><td>Dismiss the proposal</td><td><code>Mod+Shift+Backspace</code></td></tr><tr><td><code>app.palette</code></td><td>Find a story, a view or a command</td><td><code>Mod+K</code></td></tr><tr><td><code>app.openLibrary</code></td><td>Add a writing home</td><td>none</td></tr><tr><td><code>app.preferences</code></td><td>Settings</td><td><code>Mod+,</code></td></tr><tr><td><code>app.checkForUpdate</code></td><td>Check for updates</td><td>none</td></tr><tr><td><code>app.about</code></td><td>About Leathercase</td><td>none</td></tr><tr><td><code>app.sidebar</code></td><td>Collapse or expand the sidebar</td><td><code>Mod+\\</code></td></tr><tr><td><code>app.sideColumn</code></td><td>Toggle the side column</td><td><code>Mod+B</code></td></tr><tr><td><code>app.mate</code></td><td>Show or hide the mate</td><td><code>Mod+Shift+M</code></td></tr><tr><td><code>app.theme.light</code></td><td>Theme: light</td><td>none</td></tr><tr><td><code>app.theme.dark</code></td><td>Theme: dark</td><td>none</td></tr><tr><td><code>app.theme.system</code></td><td>Theme: follow the desktop</td><td>none</td></tr></tbody></table><p>The view keys (arrows, <code>n</code>, <code>f</code> and the like) and the two global keys are not in this file.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/reference/settings#hotkeys">Settings</a></li><li><a href="/guide/guide/tour">A tour of the window</a></li><li><a href="/guide/guide/find">Find, open and make</a></li><li><a href="/guide/guide/export">Export</a></li></ul>',73)])])}const y=e(n,[["render",i]]);export{u as __pageData,y as default};
